        "source_handle": "P0178",
        "field_path": [
          "study_summary_A",
          "research_scope"
        ],
        "value": "聚焦于实体瘤（特别是黑色素瘤、肾细胞癌、非小细胞肺癌等）患者接受免疫检查点抑制剂（ICIs，如抗PD-1/CTLA-4治疗）时的疗效与毒性管理。研究对象为肠道微生物组及其工程化干预策略，涵盖从基础机制到临床转化试验的综合分析。",
        "role": "evidence",
        "snapshot_ids": [
          "snapshot::092a7ef81b878efa4c53c58a",
          "snapshot::2cc8835fd55ad20a54b20c10"
        ]
