        "source_handle": "P0594",
        "field_path": [
          "study_summary_A",
          "key_findings"
        ],
        "value": {
          "conditions": "胆汁酸（BAs）",
          "finding": "次级胆汁酸如isoDCA促进Treg扩增，抑制DC功能；而UDCA通过降解TGF-β抑制Treg分化，增强抗肿瘤免疫。不同胆汁酸对CD8+ T细胞命运有截然相反的影响。"
        },
        "role": "evidence",
        "snapshot_ids": [
          "snapshot::82bffb4d0f097201933ac437"
        ]
      },
      {
